import heapq

def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0
    ids = {}
    adj = [[] for _ in range(n)]  # hubs are 0..n-1

    def get(v, c):
        key = (v, c)
        i = ids.get(key)
        if i is None:
            i = len(adj)
            ids[key] = i
            adj.append([(v, switch_cost)])  # to hub
            adj[v].append((i, 0))           # hub -> state
        return i

    for u, v, w, c in edges:
        a = get(u, c)
        b = get(v, c)
        adj[a].append((b, w))
        adj[b].append((a, w))

    INF = float('inf')
    dist = [INF] * len(adj)
    dist[s] = 0
    pq = [(0, s)]
    while pq:
        d, x = heapq.heappop(pq)
        if d > dist[x]:
            continue
        for y, w in adj[x]:
            nd = d + w
            if nd < dist[y]:
                dist[y] = nd
                heapq.heappush(pq, (nd, y))

    best = INF
    for (v, c), i in ids.items():
        if v == t and dist[i] < best:
            best = dist[i]
    return -1 if best == INF else best

def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0
    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError("no valid selection")
    if k > n // 2:
        raise ValueError("no valid selection")

    NEG = -10**18

    def linear(arr):
        base = [NEG] * (k + 1)
        base[0] = 0
        p2 = base
        p1 = base
        for v in arr:
            cur = p1[:]  # skip current element
            for j in range(1, k + 1):
                t = p2[j - 1]
                if t > NEG // 2:
                    t += v
                    if t > cur[j]:
                        cur[j] = t
            p2, p1 = p1, cur
        return p1[k]

    # Either the last element is unused, or the first element is unused
    # (at least one of them is unused in any valid circular selection).
    best = max(linear(values[:-1]), linear(values[1:]))
    if best < NEG // 2:
        raise ValueError("no valid selection")
    return best

from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R-1][C-1] == -1:
        return -1
    INF = float('inf')

    def bfs(sr, sc):
        dist = [[INF] * C for _ in range(R)]
        dist[sr][sc] = 0
        dq = deque([(sr, sc)])
        while dq:
            r, q = dq.popleft()
            d = dist[r][q] + 1
            for nr, nc in ((r+1, q), (r-1, q), (r, q+1), (r, q-1)):
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist[nr][nc] == INF:
                    dist[nr][nc] = d
                    dq.append((nr, nc))
        return dist

    d1 = bfs(0, 0)
    d2 = bfs(R-1, C-1)
    best = d1[R-1][C-1]

    m1 = {}
    m2 = {}
    for r in range(R):
        row = grid[r]
        for q in range(C):
            L = row[q]
            if L == -1:
                continue
            a = d1[r][q]
            b = d2[r][q]
            if a < m1.get(L, INF):
                m1[L] = a
            if b < m2.get(L, INF):
                m2[L] = b
    for L, a in m1.items():
        if a == INF:
            continue
        b = m2.get(L, INF)
        if b == INF:
            continue
        t = a + b + c
        if t < best:
            best = t
    return -1 if best == INF else best

def max_sessions(intervals, gap):
    if not intervals:
        return 0
    # Sort by end time (ties by start; either works)
    items = sorted(intervals, key=lambda x: (x[1], x[0]))
    count = 0
    next_free = None  # earliest allowed start for the next session
    for s, e in items:
        if next_free is None or s >= next_free:
            count += 1
            next_free = e + gap
    return count

def smallest_balanced(s):
    n = len(s)
    if n % 2:
        raise ValueError("no balanced replacement")
    q = s.count('?')
    need = n // 2 - s.count('(')   # number of '?' that must become '('
    if need < 0 or need > q:
        raise ValueError("no balanced replacement")

    res = []
    bal = 0
    used = 0
    for c in s:
        if c == '?':
            if used < need:
                c = '('
                used += 1
            else:
                c = ')'
        res.append(c)
        bal += 1 if c == '(' else -1
        if bal < 0:
            raise ValueError("no balanced replacement")
    if bal != 0:
        raise ValueError("no balanced replacement")
    return ''.join(res)

def longest_spaced_repeat(s, gap):
    n = len(s)
    best = 0
    prev = [0] * (n + 2)  # prev[j] = lcp(i+1, j)
    for i in range(n - 1, -1, -1):
        cur = [0] * (n + 2)
        si = s[i]
        for j in range(n - 1, i, -1):
            if s[j] == si:
                cur[j] = prev[j + 1] + 1
                # Longest usable length is capped by the non-overlap + gap constraint
                v = min(cur[j], j - i - gap)
                if v > best:
                    best = v
        prev = cur
    return best

def min_insertions(s, allowed):
    n = len(s)
    if n <= 1:
        return 0
    allow = set(allowed)
    INF = float('inf')
    # dp[i][j]: min insertions to make s[i..j] a palindrome (0 if i >= j)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            best = INF
            if s[i] == s[j]:
                best = dp[i + 1][j - 1] if i + 1 <= j - 1 else 0
            # insert a copy of s[i] after position j (mirrors s[i])
            if s[i] in allow:
                v = dp[i + 1][j] + 1
                if v < best:
                    best = v
            # insert a copy of s[j] before position i (mirrors s[j])
            if s[j] in allow:
                v = dp[i][j - 1] + 1
                if v < best:
                    best = v
            dp[i][j] = best
    res = dp[0][n - 1]
    return -1 if res == INF else res

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    done = set()
    visiting = set()

    for root in sorted(graph):
        if root in done:
            continue
        visiting.add(root)
        stack = [(root, iter(sorted(graph[root])))]
        while stack:
            node, it = stack[-1]
            advanced = False
            for dep in it:
                if dep in done:
                    continue
                if dep in visiting:
                    raise ValueError("dependency cycle detected at " + dep)
                visiting.add(dep)
                stack.append((dep, iter(sorted(graph[dep]))))
                advanced = True
                break
            if not advanced:
                stack.pop()
                visiting.discard(node)
                done.add(node)
                order.append(node)
    return order

import re

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
            raise ValueError("invalid amount: %r" % (amount,))

        whole, _, frac = amount.partition(".")
        cents = int(whole) * 100 + int(frac.ljust(2, "0") or "0")

        if cents <= 0:
            raise ValueError("amount must be positive")

        sender, receiver = tx["from"], tx["to"]
        balances[sender] = balances.get(sender, 0) - cents
        balances[receiver] = balances.get(receiver, 0) + cents
    return balances

from functools import wraps

def memoize(func):
    cache = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            wrapper.hits += 1
            return cache[key]
        wrapper.misses += 1              # counted even if func raises
        result = func(*args, **kwargs)   # exception propagates, nothing cached
        cache[key] = result
        return result

    wrapper.hits = 0
    wrapper.misses = 0
    return wrapper

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])

    # Range validation (against the original document)
    for start, delete, _ in ordered:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")

    # Conflict detection: same start, or overlapping delete ranges.
    # Touching ranges (next start == prev end, with different starts) are fine.
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        cur = ordered[i]
        if cur[0] == prev[0] or cur[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")

    result = list(lines)
    # Apply from the end backwards so earlier positions stay valid.
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

