class CountingBag:
    def __init__(self):
        self._counts = {}   # item -> count (only count >= 1 stored)
        self._entry = {}    # item -> entry sequence number
        self._seq = 0       # monotonically increasing entry clock
        self._total = 0     # total occurrences

    def add(self, item) -> int:
        c = self._counts.get(item, 0)
        if c == 0:
            self._entry[item] = self._seq
            self._seq += 1
        c += 1
        self._counts[item] = c
        self._total += 1
        return c

    def discard(self, item) -> bool:
        c = self._counts.get(item, 0)
        if c == 0:
            return False
        if c == 1:
            del self._counts[item]
            del self._entry[item]
        else:
            self._counts[item] = c - 1
        self._total -= 1
        return True

    def count(self, item) -> int:
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        return self._total

    def distinct(self) -> int:
        return len(self._counts)

    def most_common(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        entry = self._entry
        counts = self._counts
        if k >= len(counts):
            keys = sorted(counts, key=lambda it: (-counts[it], entry[it]))
        else:
            keys = heapq.nsmallest(
                k, counts, key=lambda it: (-counts[it], entry[it])
            )
        return [(it, counts[it]) for it in keys]

