class TTLCache:
    def __init__(self, capacity):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        self._data = OrderedDict()  # key -> (value, stored_time, ttl)
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        dead = [
            k for k, (_, t, ttl) in self._data.items()
            if ttl is not None and now >= t + ttl
        ]
        for k in dead:
            del self._data[k]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive or None")
        self._purge(now)
        if key in self._data:
            self._data[key] = (value, now, ttl)
            self._data.move_to_end(key)
            return
        if len(self._data) >= self._capacity:
            self._data.popitem(last=False)
            self._evictions += 1
        self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._data:
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._data)

from bisect import bisect_left, insort


class Leaderboard:
    def __init__(self):
        # player -> (best, seq)
        self._info = {}
        # sorted list of (-best, seq, player); seq is unique, so players are never compared
        self._order = []
        self._seq = 0

    def submit(self, player, score) -> bool:
        cur = self._info.get(player)
        if cur is not None and score <= cur[0]:
            return False  # no change at all
        if cur is not None:
            old_key = (-cur[0], cur[1], player)
            idx = bisect_left(self._order, old_key)
            del self._order[idx]
        self._seq += 1
        self._info[player] = (score, self._seq)
        insort(self._order, (-score, self._seq, player))
        return True

    def best(self, player) -> int:
        return self._info[player][0]  # raises KeyError if unknown

    def rank(self, player) -> int:
        score = self._info[player][0]  # raises KeyError if unknown
        # number of entries with -best < -score, i.e. best strictly greater
        return 1 + bisect_left(self._order, (-score,))

    def top(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        return [(p, -negs) for negs, _, p in self._order[:k]]

    def player_count(self) -> int:
        return len(self._info)

class MergeLedger:
    """Union-find with rollback (union by size, no path compression).

    Each node stores the size and value-sum of its subtree in the union-find
    forest. A root's figures are therefore the component's aggregates.
    """

    def __init__(self):
        self._parent = {}
        self._size = {}
        self._sum = {}      # subtree sums
        self._history = []  # stack of (child_root, parent_root)
        self._count = 0

    def _find(self, x):
        if x not in self._parent:
            raise KeyError(x)
        while self._parent[x] != x:
            x = self._parent[x]
        return x

    def add(self, x, value=0):
        if x in self._parent:
            raise ValueError(f"element {x!r} already exists")
        self._parent[x] = x
        self._size[x] = 1
        self._sum[x] = value
        self._count += 1

    def merge(self, a, b):
        ra = self._find(a)
        rb = self._find(b)
        if ra == rb:
            return False
        if self._size[ra] < self._size[rb]:
            ra, rb = rb, ra
        # attach rb (child) under ra (root)
        self._parent[rb] = ra
        self._size[ra] += self._size[rb]
        self._sum[ra] += self._sum[rb]
        self._history.append((rb, ra))
        self._count -= 1
        return True

    def same(self, a, b):
        return self._find(a) == self._find(b)

    def component_size(self, x):
        return self._size[self._find(x)]

    def component_value(self, x):
        return self._sum[self._find(x)]

    def add_value(self, x, delta):
        if x not in self._parent:
            raise KeyError(x)
        # update x and all its ancestors (path length is O(log n))
        while True:
            self._sum[x] += delta
            p = self._parent[x]
            if p == x:
                break
            x = p

    def components(self):
        return self._count

    def undo(self):
        if not self._history:
            raise RuntimeError("nothing to undo")
        child, root = self._history.pop()
        self._parent[child] = child
        self._size[root] -= self._size[child]
        self._sum[root] -= self._sum[child]
        self._count += 1

from bisect import bisect_left, bisect_right


class IntervalSet:
    def __init__(self):
        self._los = []   # sorted starts
        self._his = []   # corresponding ends

    @staticmethod
    def _check(lo, hi):
        if lo >= hi:
            raise ValueError(f"invalid interval: lo={lo} must be < hi={hi}")

    def add(self, lo, hi):
        self._check(lo, hi)
        los, his = self._los, self._his
        # First interval whose end >= lo (overlapping or touching on the left)
        i = bisect_left(his, lo)
        # First interval whose start > hi (anything before it overlaps or touches)
        j = bisect_right(los, hi)
        if i < j:
            lo = min(lo, los[i])
            hi = max(hi, his[j - 1])
        los[i:j] = [lo]
        his[i:j] = [hi]

    def remove(self, lo, hi):
        self._check(lo, hi)
        los, his = self._los, self._his
        # Intervals that actually overlap [lo, hi): end > lo and start < hi
        i = bisect_right(his, lo)
        j = bisect_left(los, hi)
        if i >= j:
            return
        new_los, new_his = [], []
        if los[i] < lo:
            new_los.append(los[i])
            new_his.append(lo)
        if his[j - 1] > hi:
            new_los.append(hi)
            new_his.append(his[j - 1])
        los[i:j] = new_los
        his[i:j] = new_his

    def contains(self, x):
        i = bisect_right(self._los, x) - 1
        return i >= 0 and x < self._his[i]

    def total(self):
        return sum(h - l for l, h in zip(self._los, self._his))

    def intervals(self):
        return list(zip(self._los, self._his))

    def gaps(self, lo, hi):
        self._check(lo, hi)
        los, his = self._los, self._his
        result = []
        cur = lo
        i = bisect_right(his, lo)  # first interval with end > lo
        while i < len(los) and los[i] < hi:
            if los[i] > cur:
                result.append((cur, los[i]))
            cur = max(cur, his[i])
            i += 1
        if cur < hi:
            result.append((cur, hi))
        return result

