import itertools


class TaskScheduler:
    def __init__(self):
        self._active = {}   # task_id -> [priority, seq, version]
        self._heap = []     # (-priority, seq, version, task_id)
        self._seq = itertools.count()
        self._ver = itertools.count()

    def __len__(self):
        return len(self._active)

    def _maybe_compact(self):
        # Rebuild if stale entries dominate the heap.
        if len(self._heap) > 32 and len(self._heap) > 3 * len(self._active):
            self._heap = [(-p, s, v, t) for t, (p, s, v) in self._active.items()]
            heapq.heapify(self._heap)

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError(f"task {task_id!r} already active")
        seq = next(self._seq)
        ver = next(self._ver)
        self._active[task_id] = [priority, seq, ver]
        heapq.heappush(self._heap, (-priority, seq, ver, task_id))
        self._maybe_compact()

    def reprioritize(self, task_id, priority):
        rec = self._active.get(task_id)
        if rec is None:
            raise KeyError(task_id)
        ver = next(self._ver)
        rec[0] = priority
        rec[2] = ver
        heapq.heappush(self._heap, (-priority, rec[1], ver, task_id))
        self._maybe_compact()

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]
        self._maybe_compact()

    def _clean(self):
        heap = self._heap
        active = self._active
        while heap:
            _, _, ver, tid = heap[0]
            rec = active.get(tid)
            if rec is not None and rec[2] == ver:
                return
            heapq.heappop(heap)

    def pop(self):
        self._clean()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, _, tid = heapq.heappop(self._heap)
        del self._active[tid]
        return tid

    def peek(self):
        self._clean()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][3]

    def priority_of(self, task_id):
        rec = self._active.get(task_id)
        if rec is None:
            raise KeyError(task_id)
        return rec[0]

class UndoStack:
    def __init__(self):
        self._items = []
        self._history = []  # entries: ("push", None) or ("pop", value)

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append(("push", None))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty stack")
        value = self._items.pop()
        self._history.append(("pop", value))
        return value

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        kind, value = self._history.pop()
        if kind == "push":
            self._items.pop()
        else:
            self._items.append(value)

    def __len__(self) -> int:
        return len(self._items)

class VersionedKV:
    """Key-value store with commit snapshots, point-in-time reads, and rollback."""

    def __init__(self):
        self._working = {}
        self._snapshots = []  # _snapshots[v - 1] is the immutable state at version v

    # ---- working state ----
    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    # ---- history ----
    def commit(self) -> int:
        self._snapshots.append(dict(self._working))  # independent copy
        return len(self._snapshots)

    def get_at(self, key, version):
        if not (1 <= version <= len(self._snapshots)):
            raise ValueError(f"invalid version: {version}")
        snap = self._snapshots[version - 1]
        if key not in snap:
            raise KeyError(key)
        return snap[key]

    def rollback(self, version) -> None:
        if not (0 <= version <= len(self._snapshots)):
            raise ValueError(f"invalid version: {version}")
        if version == 0:
            self._working = {}
        else:
            # copy so later writes to the working state can't alter the snapshot
            self._working = dict(self._snapshots[version - 1])

    def latest(self) -> int:
        return len(self._snapshots)

def rank_scores(scores: list) -> list[int]:
    # NaN is the only value not equal to itself; this check also avoids
    # math.isnan overflowing on very large ints.
    for s in scores:
        if s != s:
            raise ValueError("NaN scores are not allowed")

    # Sort a copy (the input is not mutated), best score first.
    ordered = sorted(scores, reverse=True)

    # The first occurrence of a value in descending order sits at index
    # equal to the number of strictly greater scores, so rank = index + 1.
    # Dict lookup uses ==/hash, so 2 and 2.0, or 0.0 and -0.0, share a key.
    rank_of = {}
    for i, s in enumerate(ordered):
        if s not in rank_of:
            rank_of[s] = i + 1

    return [rank_of[s] for s in scores]

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0:
        return ""

    units = 0
    prev_is_mark = False  # whether the previous code point was a mark joined to the current unit
    for i, ch in enumerate(s):
        is_mark = unicodedata.category(ch) in ('Mn', 'Mc', 'Me')
        if i == 0:
            # The first code point always starts a unit, mark or not.
            units = 1
        elif not is_mark:
            # A base character starts a new unit.
            if units == width:
                return s[:i]
            units += 1
        # A mark after the first code point joins the current unit.
    return s

def kth_root_floor(n: int, k: int) -> int:
    if not isinstance(n, int) or not isinstance(k, int):
        raise ValueError("n and k must be integers")
    if n < 0 or k < 1:
        raise ValueError("n must be >= 0 and k must be >= 1")
    if n < 2 or k == 1:
        return n
    bl = n.bit_length()
    if k >= bl:
        # 2**k > n (since n < 2**bl <= 2**k), and 1**k <= n
        return 1
    x = 1 << (-(-bl // k))  # >= true root
    while True:
        y = ((k - 1) * x + n // x ** (k - 1)) // k
        if y >= x:
            break
        x = y
    return x

from fractions import Fraction
import math


def allocate_shares(total: int, weights: list) -> list[int]:
    """Split `total` into integer shares proportional to `weights` using the
    largest-remainder method (ties in remainder go to the lower index).

    Exact rational arithmetic (Fraction) is used, so float weights cannot cause
    rounding errors in the quotas or the ordering of remainders.
    """
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total must be an integer")
    if total < 0:
        raise ValueError("total must be >= 0")

    if weights is None or len(weights) == 0:
        raise ValueError("weights must be non-empty")

    fracs = []
    for w in weights:
        if isinstance(w, float) and not math.isfinite(w):
            raise ValueError("weights must be finite")
        try:
            f = Fraction(w)
        except (ValueError, OverflowError, TypeError) as e:
            raise ValueError(f"invalid weight: {w!r}") from e
        if f < 0:
            raise ValueError("weights must be non-negative")
        fracs.append(f)

    W = sum(fracs)
    if W == 0:
        raise ValueError("sum of weights must be > 0")

    floors = []
    remainders = []
    for f in fracs:
        q = total * f / W
        fl = q.numerator // q.denominator
        floors.append(fl)
        remainders.append(q - fl)

    leftover = total - sum(floors)  # 0 <= leftover < number of parties

    order = sorted(range(len(fracs)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        floors[i] += 1

    return floors

from collections import deque


def round_robin(iterables: list) -> "iterator":
    def gen():
        # Only iter() is called on each input here; no items are consumed up front.
        active = deque(iter(x) for x in iterables)
        while active:
            it = active.popleft()
            try:
                value = next(it)
            except StopIteration:
                # This iterable is exhausted, so it drops out of the rotation.
                continue
            active.append(it)  # goes to the back of the rotation
            yield value        # suspends here until the next value is requested

    return gen()

import math

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if len(values) == 0:
        raise ValueError("empty input")

    W = math.fsum(weights)
    if not W > 0:
        raise ValueError("total weight must be positive")

    # Zero-weight entries contribute nothing and must never be returned.
    pairs = sorted(
        ((v, w) for v, w in zip(values, weights) if w > 0),
        key=lambda p: p[0],
    )

    threshold = W / 2 - 1e-9
    cum = 0.0
    for v, w in pairs:
        cum += w
        # For duplicate values, reaching the threshold partway through the
        # group returns the same value, so no explicit grouping is needed.
        if cum >= threshold:
            return v
    # Floating-point safety fallback: the largest positive-weight value.
    return pairs[-1][0]

import heapq

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")
    if not jobs:
        return 0
    order = sorted(jobs, key=lambda j: j[0])
    heap = []
    push = heapq.heappush
    pushpop = heapq.heappushpop
    size = 0
    for d, p in order:
        if size < cap * d:
            push(heap, p)
            size += 1
        else:
            pushpop(heap, p)
    return sum(heap)

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    n = len(intervals)
    starts = sorted(iv[0] for iv in intervals)
    ends = sorted(iv[1] for iv in intervals)
    best = 0
    best_t = 0
    j = 0
    for i in range(n):
        t = starts[i]
        if i + 1 < n and starts[i + 1] == t:
            continue
        while j < n and ends[j] <= t:
            j += 1
        load = i + 1 - j
        if load > best:
            best = load
            best_t = t
    return (best, best_t)

from collections import deque

def count_stable_windows(readings: list[int], tol: int) -> int:
    n = len(readings)
    if n == 0:
        return 0
    maxd = deque()  # indices, values decreasing
    mind = deque()  # indices, values increasing
    l = 0
    total = 0
    a = readings
    for r in range(n):
        v = a[r]
        while maxd and a[maxd[-1]] <= v:
            maxd.pop()
        maxd.append(r)
        while mind and a[mind[-1]] >= v:
            mind.pop()
        mind.append(r)
        while a[maxd[0]] - a[mind[0]] > tol:
            l += 1
            if maxd[0] < l:
                maxd.popleft()
            if mind[0] < l:
                mind.popleft()
        total += r - l + 1
    return total

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}: must be a tuple of exactly 3 elements")
        category, amount, refunded = row

        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}: category must be a non-empty str")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}: amount must be an int or float (not bool)")

        # `not amount >= 0` also rejects NaN, which is not a valid amount >= 0
        if not amount >= 0:
            raise ValueError(f"row {i}: amount must be >= 0")

        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}: refunded must be a bool")

        value = float(amount)
        entry = result.get(category)
        if entry is None:
            result[category] = {
                "count": 1,
                "gross": value,
                "net": 0.0 if refunded else value,
                "largest": value,
            }
        else:
            entry["count"] += 1
            entry["gross"] += value
            if not refunded:
                entry["net"] += value
            if value > entry["largest"]:
                entry["largest"] = value

    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    for bound in (low, high):
        if isinstance(bound, bool) or not isinstance(bound, (int, float)):
            raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"element at index {i} must be an int or float")
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)
    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    # Explicit stack of iterators; len(stack) - 1 is the current nesting depth
    # of the list being iterated (top-level list is depth 0).
    stack = [iter(nested)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list) and len(stack) <= max_depth:
            stack.append(iter(item))
        else:
            result.append(item)
    return result

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    name_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_")
    out = []
    n = len(template)
    i = 0
    while i < n:
        c = template[i]
        if c == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            j = i + 1
            while j < n and template[j] in name_chars:
                j += 1
            if j >= n:
                raise ValueError("unclosed placeholder at position %d" % i)
            if template[j] != "}":
                raise ValueError("invalid placeholder at position %d" % i)
            if j == i + 1:
                raise ValueError("empty placeholder at position %d" % i)
            name = template[i + 1:j]
            try:
                value = context[name]
            except KeyError:
                raise KeyError(name)
            out.append(str(value))
            i = j + 1
        elif c == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position %d" % i)
        else:
            out.append(c)
            i += 1
    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    digits = "0123456789"
    ops = ("+", "-", "*", "/")

    def parse_int(tok):
        # Returns an int, or None if tok is not a valid literal.
        # Parsed in chunks to avoid the interpreter's int/str digit limit.
        sign = 1
        body = tok
        if body[:1] in ("+", "-"):
            if body[0] == "-":
                sign = -1
            body = body[1:]
        if body == "":
            return None
        for ch in body:
            if ch not in digits:
                return None
        v = 0
        step = 1000
        for j in range(0, len(body), step):
            chunk = body[j:j + step]
            v = v * (10 ** len(chunk)) + int(chunk)
        return sign * v

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError("token %d is not a string" % i)
        if tok in ops:
            if len(stack) < 2:
                raise ValueError("stack underflow at token %d" % i)
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero at token %d" % i)
                q = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    q = -q
                stack.append(q)
        else:
            v = parse_int(tok)
            if v is None:
                raise ValueError("unknown token at token %d: %r" % (i, tok))
            stack.append(v)

    if len(stack) > 1:
        raise ValueError("leftover operands")
    return stack[0]

def _walk(node, parts):
    if not parts:
        return node
    seg = parts[0]
    rest = parts[1:]
    if isinstance(node, dict):
        if seg not in node:
            raise KeyError(seg)
        return _walk(node[seg], rest)
    if isinstance(node, list):
        body = seg[1:] if seg.startswith("-") else seg
        if not (body and body.isascii() and body.isdigit()):
            raise ValueError("invalid index: %r" % (seg,))
        try:
            idx = int(seg)
        except ValueError:
            # absurdly long digit strings hit int's conversion limit
            raise IndexError("index %s out of range" % seg)
        if idx < -len(node) or idx >= len(node):
            raise IndexError("index %s out of range" % seg)
        return _walk(node[idx], rest)
    raise TypeError(
        "cannot descend into %s with remaining segment %r"
        % (type(node).__name__, seg)
    )


def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    parts = path.split(".")
    if "" in parts:
        raise ValueError("empty segment in path %r" % (path,))
    return _walk(data, parts)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    # Count occurrences; dicts preserve insertion order, so the keys
    # are in order of first occurrence.
    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1

    candidates = [(value, cnt) for value, cnt in counts.items()]
    n = len(candidates)
    limit = k if k < n else n

    result = []
    for _ in range(limit):
        best_idx = 0
        best_count = candidates[0][1]
        for i in range(1, len(candidates)):
            c = candidates[i][1]
            # Strict comparison keeps the earliest-occurring value on ties.
            if c > best_count:
                best_count = c
                best_idx = i
        value, cnt = candidates.pop(best_idx)
        result.append((value, cnt))

    return result
